package sip

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

// BranchMagicCookie starts every branch generated by an RFC 3261
// client, which is how a server knows the branch is unique (RFC 3261
// 8.1.1.7, 17.2.3).
const BranchMagicCookie = "z9hG4bK"

// Via is one Via value (RFC 3261 20.42):
//
//	SIP/2.0/UDP 192.0.2.1:5060;branch=z9hG4bK776asdhds;rport
//
// The parameters that matter here are branch (8.1.1.7), received
// (18.2.1), and rport (RFC 3581). An rport without a value is the
// client's request that the server fill it in.
type Via struct {
	Transport string // "UDP", "TCP", ...; upper case
	Host      string // sent-by host; an IPv6 address without brackets
	Port      int    // sent-by port; 0 when absent
	Params    Params
}

func ParseVia(value string) (Via, error) {
	protocolAndSentBy, params, _ := strings.Cut(value, ";")
	// sent-protocol = protocol-name SLASH protocol-version SLASH
	// transport, and SLASH allows whitespace on both sides (RFC 3261
	// 25.1).
	parts := strings.SplitN(protocolAndSentBy, "/", 3)
	if len(parts) != 3 ||
		!strings.EqualFold(strings.TrimSpace(parts[0]), "SIP") ||
		strings.TrimSpace(parts[1]) != "2.0" {
		return Via{}, fmt.Errorf("sip: Via %q is not SIP/2.0", value)
	}
	fields := strings.Fields(parts[2])
	if len(fields) < 2 {
		return Via{}, fmt.Errorf("sip: Via %q has no sent-by", value)
	}
	// COLON in sent-by may also have whitespace around it.
	sentBy := strings.Join(fields[1:], "")
	v := Via{Transport: strings.ToUpper(fields[0]), Params: parseParams(params)}
	var err error
	if v.Host, v.Port, err = splitHostPort(sentBy); err != nil {
		return Via{}, fmt.Errorf("sip: Via %q: %w", value, err)
	}
	return v, nil
}

func (v Via) String() string {
	return SIPVersion + "/" + v.Transport + " " + v.SentBy() + v.Params.String()
}

// SentBy is host[:port] as the client wrote it.
func (v Via) SentBy() string { return joinHostPort(v.Host, v.Port) }

func (v Via) Branch() string {
	b, _ := v.Params.Get("branch")
	return b
}

// CSeq is the value of the CSeq header field (RFC 3261 20.16).
type CSeq struct {
	Number uint32
	Method Method
}

func ParseCSeq(value string) (CSeq, error) {
	fields := strings.Fields(value)
	if len(fields) != 2 {
		return CSeq{}, fmt.Errorf("sip: malformed CSeq %q", value)
	}
	n, err := strconv.ParseUint(fields[0], 10, 32)
	if err != nil {
		return CSeq{}, fmt.Errorf("sip: malformed CSeq number %q", value)
	}
	return CSeq{Number: uint32(n), Method: Method(fields[1])}, nil
}

func (c CSeq) String() string {
	return strconv.FormatUint(uint64(c.Number), 10) + " " + string(c.Method)
}

// ParseRSeq reads RSeq, the number of a reliable provisional response,
// from 1 to 2**32-1 (RFC 3262 7.1).
func ParseRSeq(value string) (uint32, error) {
	n, err := strconv.ParseUint(strings.TrimSpace(value), 10, 32)
	if err != nil || n == 0 {
		return 0, fmt.Errorf("sip: malformed RSeq %q", value)
	}
	return uint32(n), nil
}

// RAck is the value of the RAck header field of a PRACK (RFC 3262 7.2):
// the RSeq of the provisional response it acknowledges, and the CSeq of
// that response.
//
//	RAck: 776656 1 INVITE
type RAck struct {
	RSeq uint32
	CSeq CSeq
}

func ParseRAck(value string) (RAck, error) {
	rseq, cseq, _ := strings.Cut(strings.TrimSpace(value), " ")
	n, err := ParseRSeq(rseq)
	if err != nil {
		return RAck{}, fmt.Errorf("sip: malformed RAck %q", value)
	}
	c, err := ParseCSeq(cseq)
	if err != nil {
		return RAck{}, fmt.Errorf("sip: malformed RAck %q", value)
	}
	return RAck{RSeq: n, CSeq: c}, nil
}

func (r RAck) String() string {
	return strconv.FormatUint(uint64(r.RSeq), 10) + " " + r.CSeq.String()
}

// ParseDeltaSeconds reads delta-seconds, the value of Expires and of
// the Contact expires parameter. RFC 3261 20.19 bounds it by 2**32-1,
// and 10.2 lets larger values count as 2**32-1.
func ParseDeltaSeconds(value string) (uint32, error) {
	value = strings.TrimSpace(value)
	if value == "" || strings.TrimLeft(value, "0123456789") != "" {
		return 0, fmt.Errorf("sip: malformed delta-seconds %q", value)
	}
	n, err := strconv.ParseUint(value, 10, 32)
	if err != nil {
		return math.MaxUint32, nil
	}
	return uint32(n), nil
}

// ParseMaxForwards reads Max-Forwards, an integer from 0 to 255 (RFC
// 3261 20.22).
func ParseMaxForwards(value string) (int, error) {
	n, err := strconv.Atoi(strings.TrimSpace(value))
	if err != nil || n < 0 || n > 255 {
		return 0, fmt.Errorf("sip: malformed Max-Forwards %q", value)
	}
	return n, nil
}
